import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.EnumSet;

public class SecureChunkStorageEngine {
    public void persistChunk(Path targetPath, ByteBuffer chunkData) throws IOException {
        EnumSet<StandardOpenOption> options = EnumSet.of(
            StandardOpenOption.CREATE,
            StandardOpenOption.WRITE,
            StandardOpenOption.APPEND
        );

        try (FileChannel fileChannel = FileChannel.open(targetPath, options)) {
            fileChannel.lock(); // Acquire exclusive lock for thread-safe block append
            while (chunkData.hasRemaining()) {
                fileChannel.write(chunkData);
            }
            fileChannel.force(false); // Ensure durability to disk
        } catch (IOException e) {
            // Translate low-level disk exceptions into domain context
            throw new StorageEngineException("Failed to persist file block to path: " + targetPath, e);
        }
    }
}
